mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.FROM_ID,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.TO_ID,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.RELATION_ID,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.FROM_TYPE_CD = #{fromTypeCd}
AND T1.FROM_ID = #{fromId}
AND T1.TO_TYPE_CD = #{toTypeCd}
AND T1.TO_ID = #{toId}
AND T1.RELATION_TYPE_CD = #{relationTypeCd}
AND T1.CRITICAL_YN = #{criticalYn}

  AND (T1.FROM_ID = #{rootId} OR T1.TO_ID = #{rootId})

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.RELATION_ID AS RELATION_ID, T1.FROM_TYPE_CD AS FROM_TYPE_CD, T1.FROM_ID AS FROM_ID,
           T1.TO_TYPE_CD AS TO_TYPE_CD, T1.TO_ID AS TO_ID, T1.RELATION_TYPE_CD AS RELATION_TYPE_CD,
           T1.CRITICAL_YN AS CRITICAL_YN, T1.REMARK AS REMARK, T1.REG_USER_ID AS REG_USER_ID, T1.REG_DTM AS REG_DTM
      FROM TB_IF_ASSET_RELATION_PILOT T1

     ORDER BY T1.CRITICAL_YN DESC, T1.RELATION_ID
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

mapper.insert:
INSERT INTO TB_IF_ASSET_RELATION_PILOT (
  RELATION_ID, FROM_TYPE_CD, FROM_ID, TO_TYPE_CD, TO_ID, RELATION_TYPE_CD, CRITICAL_YN, REMARK, REG_USER_ID, REG_DTM
) VALUES (
  #{relationId}, #{fromTypeCd}, #{fromId}, #{toTypeCd}, #{toId}, #{relationTypeCd}, #{criticalYn}, #{remark}, #{regUserId}, #{regDtm}
)

mapper.delete:
DELETE FROM TB_IF_ASSET_RELATION_PILOT
 WHERE RELATION_ID IN
#{id}
